args.command:
cd /workspace/probe/cli && run(){ echo "### CMD: $*"; "$@" > /tmp/o.txt 2> /tmp/e.txt < /dev/null; echo "EXIT=$?"; echo "--stdout--"; cat /tmp/o.txt; echo "--stderr--"; cat /tmp/e.txt; echo; }
# clobber: out.wav already exists (created earlier? ensure)
cp t1.wav exists.wav
run /workspace/executable t1.wav exists.wav trim 0 0.5
run /workspace/executable --no-clobber t1.wav exists.wav trim 0 0.5
echo "n" | { /workspace/executable --no-clobber t1.wav exists.wav trim 0 0.5 > /tmp/o.txt 2>/tmp/e.txt; echo "### with 'n' piped EXIT=$?"; echo "--stdout--"; cat /tmp/o.txt; echo "--stderr--"; cat /tmp/e.txt; }
echo "y" | { /workspace/executable --no-clobber t1.wav exists.wav trim 0 0.5 > /tmp/o.txt 2>/tmp/e.txt; echo "### with 'y' piped EXIT=$?"; echo "--stdout--"; cat /tmp/o.txt; echo "--stderr--"; cat /tmp/e.txt; }
run /workspace/executable t1.wav -d trim 0 0.1
run /workspace/executable -d out.wav trim 0 0.1
